# Standalone fail-closed verifier, Python 3, no imports, no IO, no prints.
# Pure function verify() -> bool; the calling harness treats True as PASS.
# Witness is embedded: n = 4, subsets as bitmasks 0..15.

def popcount(v):
    c = 0
    while v:
        c += v & 1
        v >>= 1
    return c

def verify():
    hered = []
    for F in range(1 << 16):
        ok = True
        for s in range(16):
            if (F >> s) & 1:
                for t in range(16):
                    if (t & s) == t and not ((F >> t) & 1):
                        ok = False
                        break
                if not ok:
                    break
        if ok:
            hered.append(F)
    # Dedekind number M(4) = 168, fail-closed count check
    if len(hered) != 168:
        return False
    for F in hered:
        best_i = 0
        for G in range(F + 1):
            if (G & ~F) != 0:
                continue
            ok = True
            for a in range(16):
                if (G >> a) & 1:
                    for b in range(16):
                        if (G >> b) & 1 and (a & b) == 0:
                            ok = False
                            break
                    if not ok:
                        break
            if ok and popcount(G) > best_i:
                best_i = popcount(G)
        best_s = 0
        for x in range(4):
            cnt = 0
            for s in range(16):
                if ((F >> s) & 1) and ((s >> x) & 1):
                    cnt += 1
            if cnt > best_s:
                best_s = cnt
        if best_i != best_s:
            return False
    return True
